function enterSpace(){
document.getElementById("entry").style.opacity="0";
document.getElementById("entry").style.visibility="hidden";
document.getElementById("home").style.opacity="1";
document.getElementById("home").style.visibility="visible";

audio.play().then(()=>{
    playButton.textContent="Ⅱ";
}).catch(()=>{
    playButton.textContent="▶";
});
}

const menuButtons=document.querySelectorAll(".menu-btn");
const infoPanels=document.querySelectorAll(".info-panel");

menuButtons.forEach(button=>{
button.addEventListener("click",()=>{
if(button.dataset.panel==="backPanel"){
returnToStart();
return;
}
const target=document.getElementById(button.dataset.panel);
const wasOpen=target.classList.contains("show");
menuButtons.forEach(b=>b.classList.remove("active"));
infoPanels.forEach(p=>p.classList.remove("show"));
if(!wasOpen){
button.classList.add("active");
target.classList.add("show");
}
});
});

document.getElementById("homePanel").classList.add("show");
function returnToStart(){
    audio.pause();
    audio.currentTime=0;
    playButton.textContent="▶";
    progress.style.width="0%";
    time.textContent="0:00";

    document.getElementById("home").style.opacity="0";
    document.getElementById("home").style.visibility="hidden";
    document.getElementById("entry").style.opacity="1";
    document.getElementById("entry").style.visibility="visible";

    menuButtons.forEach(b=>b.classList.remove("active"));
    infoPanels.forEach(p=>p.classList.remove("show"));
    document.querySelector('[data-panel="homePanel"]').classList.add("active");
    document.getElementById("homePanel").classList.add("show");
}


const audio=document.getElementById("audio");
if(audio) audio.src="data:audio/mpeg;base64,";
const playButton=document.querySelector(".play");
const time=document.getElementById("time");
const progress=document.getElementById("progress");

function togglePlay(){
if(audio.paused){
audio.play().then(()=>playButton.textContent="Ⅱ").catch(()=>alert("El archivo EXCXSXS.mp3 no está disponible en esta carpeta."));
}else{
audio.pause();
playButton.textContent="▶";
}
}

audio.addEventListener("timeupdate",()=>{
if(audio.duration){
progress.style.width=((audio.currentTime/audio.duration)*100)+"%";
const m=Math.floor(audio.currentTime/60);
const s=String(Math.floor(audio.currentTime%60)).padStart(2,"0");
time.textContent=m+":"+s;
}
});

audio.addEventListener("ended",()=>{
playButton.textContent="▶";
progress.style.width="0%";
time.textContent="0:00";
});
